  },
  "high_order_assessment": [
    {
      "active_model_action": true,
      "citations": [
        {
          "event_id": "lite_evt_00101",
          "explanation": "The doctor used non-blaming, plain-language validation of family concerns while maintaining urgency.",
          "quote": "家里老人说“看着挺好别折腾”"
        },
        {
          "event_id": "lite_evt_00250",
          "explanation": "The doctor reassured and coached the anxious caregiver in concrete, supportive language.",
          "quote": "你做得太棒了，真的"
        }
      ],
      "completion": "complete",
      "explanation": "The doctor repeatedly used calm, caregiver-sensitive language, validated family fatigue and fear, avoided shaming, and preserved urgency for ultrasound and emergency thresholds.",
      "ho_id": "HO1",
      "meaningful_trajectory_impact": true,
      "triggered": true
    },
    {
      "active_model_action": true,
      "citations": [
        {
          "event_id": "lite_evt_00101",
          "explanation": "The doctor gave an exact phone script to reduce missed questions when the caregiver was tired.",
          "quote": "你照着念就不会漏"
        },
        {
          "event_id": "lite_evt_00185",
          "explanation": "The doctor adapted the plan when the preferred clinic was unavailable.",
          "quote": "新生儿科门诊完全可以处理"
        }
      ],
      "completion": "complete",
      "explanation": "The doctor offered practical execution steps despite fatigue, family opposition, and scheduling barriers: phone scripts, fallback clinic choice, document preparation, and appointment confirmation.",
      "ho_id": "HO2",
      "meaningful_trajectory_impact": true,
      "triggered": true
    },
    {
      "active_model_action": true,
      "citations": [
        {
          "event_id": "lite_evt_00079",
          "explanation": "The doctor corrected the caregiver’s conflation of hospital medication records with take-home medicines in simple terms.",
          "quote": "都是住院时用的针剂"
        },
        {
          "event_id": "lite_evt_00201",
          "explanation": "The caregiver later confirmed the misunderstanding had been resolved in line with the doctor's framing.",
          "quote": "不是让我们回家喂的"
        }
      ],
      "completion": "complete",
      "explanation": "The doctor clearly explained that glucose, sodium bicarbonate, saline, and surfactant were inpatient/procedure records, not home medicines, while still requiring confirmation of true discharge medications.",
      "ho_id": "HO3",
